head.script:
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드 처리
        $c.bns.BnsPanelToGroupBox(panel_1);
        // 호출파라미터설정
        scwin.setParam();
        // 목록조회
        if (txb_IsurNm.getValue().length > 0) scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25001.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25001.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25001.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name txb_IsurNm_onkeypress
 * @description txb_IsurNm onkeypress 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsurNm_onkeypress = function() {
    try {
        if (window.event.keyCode === 13) scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS25001.txb_IsurNm_onkeypress" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25001.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        let arrPar = new Array();
        arrPar[0] = {
            ISUR_CD: dts_List.getCellData(row, "ISUR_CD"),
            ISUR_NM: dts_List.getCellData(row, "ISUR_NM")
        };
        scwin.fn_SetPar(arrPar);
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS25001.grd_List_OnDblClick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description 발행기관을 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    let param = '';
    param += "&{P}V_ISUR_NM=" + txb_IsurNm.getValue();

    // 상세조회
    const dsNm = 'BNS_ISUR_INFO';
    const qryId = 'lds.stf.bnscommon.select.listIsurCd';
    $c.bns.fn_SearchBns('ULDBNS25001.xml', dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        let arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        if (typeof(arrPar[0].ISUR_CD) !== 'undefined' &&
            arrPar[0].ISUR_CD !== '') {
            txb_IsurNm.setValue(arrPar[0].ISUR_CD);
        } else if (typeof(arrPar[0].ISUR_NM) !== 'undefined' &&
            arrPar[0].ISUR_NM.length > 0) {
            txb_IsurNm.setValue(arrPar[0].ISUR_NM);
        }
    }
};
